def priority_v2(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Normalize parameters
    SH_normalized = SH / (SH + 1)
    EMP_normalized = EMP / (EMP + 1)
    RI_normalized = RI / (RI + 1)
    DIFF_normalized = DIFF / (1000000000 + 1)
    AVG_normalized = abs(AVG - CUR) / (1000000 + 1)

    # Adaptive nonlinear weights based on free space
    if EMP > 10:
        weight_EMP = 0.30
    elif EMP > 5:
        weight_EMP = 0.40
    else:
        weight_EMP = 0.50

    # Adaptive nonlinear weights based on number of containers
    if SH > 20:
        weight_SH = 0.02
    elif SH > 10:
        weight_SH = 0.03
    else:
        weight_SH = 0.04

    # Adaptive nonlinear weights based on blocking containers
    if RI > 10:
        weight_RI = 0.35
    elif RI > 5:
        weight_RI = 0.25
    else:
        weight_RI = 0.20

    # Adaptive nonlinear weights based on DIFF
    if DIFF > 1000000:
        weight_DIFF = 0.10
    else:
        weight_DIFF = 0.15

    # Adaptive nonlinear weights based on AVG
    if AVG_normalized < 0.15:
        weight_AVG = 0.20
    elif AVG_normalized < 0.35:
        weight_AVG = 0.25
    else:
        weight_AVG = 0.30

    # Calculate the final priority score
    priority = (
        weight_SH * SH_normalized +
        weight_EMP * (1 - EMP_normalized) +
        weight_RI * RI_normalized +
        weight_DIFF * (1 - DIFF_normalized) +
        weight_AVG * AVG_normalized
    )
    return priority
